#!/usr/bin/env node
/**
 * Bundle Basis Universal transcoder with inlined WASM
 * 
 * This script reads the basis_transcoder.js and basis_transcoder.wasm files
 * and generates a TypeScript module with everything inlined.
 */

const fs = require('fs');
const path = require('path');

const LIBS_DIR = path.join(__dirname, '..', 'libs');
const OUTPUT_FILE = path.join(__dirname, '..', 'src', 'basis-transcoder.ts');

// Read the files
const basisJs = fs.readFileSync(path.join(LIBS_DIR, 'basis_transcoder.js'), 'utf8');
const basisWasm = fs.readFileSync(path.join(LIBS_DIR, 'basis_transcoder.wasm'));
const wasmBase64 = basisWasm.toString('base64');

// Escape the JS code for embedding in a string
const escapedBasisJs = basisJs
  .replace(/\\/g, '\\\\')
  .replace(/`/g, '\\`')
  .replace(/\$/g, '\\$');

// Create the bundled TypeScript module
const bundledCode = `/**
 * Bundled Basis Universal Transcoder
 * Generated by scripts/bundle-basis.js
 * 
 * Both JS and WASM are inlined - no external files needed.
 */

// Inlined WASM as base64
const WASM_BASE64 = "${wasmBase64}";

// Inlined Basis JS code
const BASIS_JS_CODE = \`${escapedBasisJs}\`;

// Convert base64 to ArrayBuffer
function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

// Pre-decoded WASM binary (lazy)
let wasmBinary: ArrayBuffer | null = null;
function getWasmBinary(): ArrayBuffer {
  if (!wasmBinary) {
    wasmBinary = base64ToArrayBuffer(WASM_BASE64);
  }
  return wasmBinary;
}

// Basis module singleton
let basisModulePromise: Promise<any> | null = null;
let basisModule: any = null;

export async function initBasisTranscoder(): Promise<any> {
  if (basisModule) return basisModule;
  if (basisModulePromise) return basisModulePromise;
  
  basisModulePromise = (async () => {
    // Execute the inlined Basis JS to get the BASIS factory
    const BASISFactory = new Function(BASIS_JS_CODE + '; return BASIS;')();
    
    // Call BASIS factory with wasmBinary option
    const module = await BASISFactory({
      wasmBinary: getWasmBinary(),
    });
    
    module.initializeBasis();
    basisModule = module;
    
    // Set on window for compatibility
    if (typeof window !== 'undefined') {
      (window as any).BASIS = module;
    }
    
    return module;
  })();
  
  return basisModulePromise;
}

export function getBasisModule(): any {
  return basisModule;
}

export default initBasisTranscoder;
`;

fs.writeFileSync(OUTPUT_FILE, bundledCode);
console.log('Generated ' + OUTPUT_FILE + ' (' + (bundledCode.length / 1024).toFixed(1) + ' KB)');
